/** Bouwt een realistische testmail: HTML + tekst, inline afbeelding, PDF-bijlage, doorgestuurde mail, umlauts. */
const PNG = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==",
  "base64",
);
const PDF = Buffer.from("%PDF-1.4\n1 0 obj<<>>endobj\ntrailer<<>>\n%%EOF\n");

export function makeEml(): Uint8Array {
  const b64 = (b: Buffer) => b.toString("base64").replace(/.{76}/g, "$&\r\n");
  const lines = [
    "Received: from mx.example.com by mail.bakertilly.nl; Mon, 9 Nov 2026 09:14:00 +0100",
    "From: =?utf-8?q?J=C3=BCrgen_de_Vries?= <jurgen.devries@rabobank.nl>",
    "To: \"Niemeijer, Alexander\" <a.niemeijer@bakertilly.nl>, Piet Jansen <p.jansen@bakertilly.nl>",
    "Cc: legal@example.com",
    "Subject: RE: FW: [EXTERN] Concept SPA Project Alpha =?utf-8?q?=E2=80=93?= opmerkingen",
    "Date: Mon, 9 Nov 2026 09:13:27 +0100",
    "Message-ID: <abc123@rabobank.nl>",
    "MIME-Version: 1.0",
    'Content-Type: multipart/mixed; boundary="MIX"',
    "",
    "--MIX",
    'Content-Type: multipart/related; boundary="REL"',
    "",
    "--REL",
    'Content-Type: multipart/alternative; boundary="ALT"',
    "",
    "--ALT",
    "Content-Type: text/plain; charset=utf-8",
    "Content-Transfer-Encoding: quoted-printable",
    "",
    "Beste Alexander,=0D=0A=0D=0AHierbij onze opmerkingen op de concept-SPA voor Project Alpha. Graag de =",
    "earn-out clausule en de WACC-onderbouwing nog eens bekijken.=0D=0A=0D=0AGroet, J=C3=BCrgen",
    "--ALT",
    "Content-Type: text/html; charset=utf-8",
    "",
    '<html><body><p>Beste Alexander,</p><p>Hierbij onze opmerkingen op de concept-SPA voor Project Alpha.</p><img src="cid:logo123@rabo"><p>Groet, Jürgen</p></body></html>',
    "--ALT--",
    "--REL",
    "Content-Type: image/png",
    "Content-Transfer-Encoding: base64",
    "Content-ID: <logo123@rabo>",
    "Content-Disposition: inline; filename=logo.png",
    "",
    b64(PNG),
    "--REL--",
    "--MIX",
    'Content-Type: application/pdf; name="Concept SPA v3 – markup.pdf"',
    "Content-Transfer-Encoding: base64",
    'Content-Disposition: attachment; filename*=utf-8\'\'Concept%20SPA%20v3%20%E2%80%93%20markup.pdf',
    "",
    b64(PDF),
    "--MIX",
    "Content-Type: message/rfc822",
    "Content-Disposition: attachment",
    "",
    "From: someone@example.com",
    "To: jurgen.devries@rabobank.nl",
    "Subject: Oorspronkelijke vraag",
    "Date: Fri, 6 Nov 2026 16:00:00 +0100",
    "",
    "Dit is de doorgestuurde mail.",
    "--MIX--",
    "",
  ];
  return new Uint8Array(Buffer.from(lines.join("\r\n"), "utf8"));
}
